import re
import json
import zlib
import base64
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import Application, CommandHandler, MessageHandler, filters, ContextTypes

BOT_TOKEN = "9212713986:AAH3GRUWov_9O76LXTBpmccU1PpJ3QSpnQQ"
COMPRESSED_DATA = ""

# Ye line data ko memory me load nahi karti, bas ek string rakhti hai
def get_data(roll_no):
    try:
        raw = zlib.decompress(base64.b64decode(COMPRESSED_DATA)).decode('utf-8')
        db = json.loads(raw)
        return db.get(roll_no)
    except:
        return None

async def start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text("*🎓 NSP Scholarship Merit List Checker Bot!*\n\n*📩 अपना Roll Code और Roll Number भेजें।*\n\n*📝 Example:* `17089-26020020`", parse_mode="Markdown")

async def search(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    text = update.message.text.strip()
    if not re.match(r"^\d{5}-\d{8}$", text):
        await update.message.reply_text("*❌ गलत फॉर्मेट!*", parse_mode="Markdown")
        return
        
    d = get_data(text)
    if not d:
        await update.message.reply_text("*❌ डेटा नहीं मिला।*", parse_mode="Markdown")
        return
        
    header = "🎓 __*NSP Scholarship Merit List Checker Bot!*__\n\n"
    gender = "Female" if d[4] == "F" else "Male"
    ph = "YES" if d[6] == "Y" else "NO"
    faculty_map = {"SCI": "SCIENCE", "HUM": "HUMANITIES", "COM": "COMMERCE"}
    fac = faculty_map.get(d[7], d[7])
    
    details = f"```\n👤 Name       : {d[0]}\n📄 Roll No.   : {text}\n📅 Passing    : {d[1]}\n🎂 DOB        : {d[2]}\n👨 Father     : {d[3]}\n⚧ Gender     : {gender}\n🏷 Category   : {d[5]}\n♿ PH         : {ph}\n🎓 Faculty    : {fac}\n🏆 Marks      : {d[8]} / {d[9]}\n📊 Percentage : {d[10]}%\n```\n"
    footer = "\n🎉 *You are Eligible! for NSP CSS Scholarship!*"
    keyboard = [[InlineKeyboardButton("Apply Now ✅", url="https://scholarships.gov.in/"), InlineKeyboardButton("Join For Update 📢", url="https://t.me/PPUPatnaInfo")]]
    
    await update.message.reply_text(header + details + footer, parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(keyboard))

def main():
    app = Application.builder().token(BOT_TOKEN).build()
    app.add_handler(CommandHandler("start", start))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, search))
    print("[*] Bot is running...")
    app.run_polling()

if __name__ == "__main__":
    main()
